// Порог релевантности: ниже — кандидат считается неподходящим (тюнится по живым тестам)
const MIN_SCORE = 0.2;
const query = $('Chat Trigger').first().json.chatInput;

const byName = {};
for (const item of $input.all()) {
  const j = item.json || {};
  // Pinecone load: {document: {pageContent, metadata}, score} либо плоский вариант
  const doc = j.document ?? j;
  const meta = doc.metadata ?? j.metadata ?? {};
  const score = typeof j.score === 'number' ? j.score : 0;
  const name = meta.candidate_name;
  if (!name) continue; // пустой/служебный item
  const cur = byName[name];
  if (!cur) {
    byName[name] = {
      name,
      score,
      // чанк без skills = устаревшая запись: его position не берём за истину
      position: meta.skills ? (meta.position || '') : '',
      skills: meta.skills || '',
      email: meta.email || ''
    };
  } else {
    // несколько чанков одного кандидата: max score, поля — из актуальных чанков (с polem skills)
    cur.score = Math.max(cur.score, score);
    if (meta.skills) {
      cur.skills = cur.skills || meta.skills;
      cur.position = cur.position || meta.position || '';
    }
    cur.email = cur.email || meta.email || '';
  }
}

const candidates = Object.values(byName)
  .filter(c => c.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10)
  .map(c => ({
    name: c.name,
    score: Math.round(c.score * 1000) / 1000,
    position: c.position || 'не указано',
    skills: c.skills || 'не указано',
    email: c.email || 'не указано'
  }));

return [{ json: { query, found: candidates.length > 0, candidates } }];
